sys_atf_step.step_config:
{"script": "(function(outputs, steps, stepResult, assertEqual) {
 var id = steps('criar_cliente_com_agendamento').record_id;
 var cli = new GlideRecord('x_espaco_cliente');
 cli.get(id);
 assertEqual({ name: 'email anonimizado', shouldbe: 'anonimizado@lgpd.local', value: cli.getValue('email') });

 var log = new GlideRecord('x_espaco_log_auditoria');
 log.addQuery('registro_id', id);
 log.addQuery('acao', 'ANONIMIZACAO');
 log.query();
 assertEqual({ name: 'log de auditoria criado', shouldbe: true, value: log.hasNext() });
})(outputs, steps, stepResult, assertEqual);"}
